import axios from 'axios';
import { environment } from './environment';
import { queryStringParams } from './query-string';
import { Locale } from '../types';

interface IFeatureToggles {
    [key: string]: { [key: string]: { featureToggles: string } }
}
const featureToggleUrls: IFeatureToggles = {
    'en-gb': {
        debug: {
            featureToggles: 'https://dev-www.tombolaarcade.co.uk/api/v3/featuretoggle'
        },
        dev: {
            featureToggles: 'https://dev-www.tombolaarcade.co.uk/api/v3/featuretoggle'
        },
        stage: {
            featureToggles: 'https://stage-www.tombolaarcade.co.uk/api/v3/featuretoggle'
        },
        live: {
            featureToggles: 'https://www.tombolaarcade.co.uk/api/v3/featuretoggle'
        }
    },
    'it-it': {
        debug: { featureToggles: 'https://dev-www.tombola.it/api/v2/featuretoggle' },
        dev: { featureToggles: 'https://dev-www.tombola.it/api/v2/featuretoggle' },
        stage: { featureToggles: 'https://stage-www.tombola.it/api/v2/featuretoggle' },
        live: { featureToggles: 'https://www.tombola.it/api/v2/featuretoggle' }
    },
    'es-es': {
        debug: { featureToggles: 'https://dev-www.tombola.es/api/v2/featuretoggle' },
        dev: { featureToggles: 'https://dev-www.tombola.es/api/v2/featuretoggle' },
        stage: { featureToggles: 'https://stage-www.tombola.es/api/v2/featuretoggle' },
        live: { featureToggles: 'https://www.tombola.es/api/v2/featuretoggle' }
    },
    'dk-dk': {
        debug: { featureToggles: 'https://dev-www.tombola.dk/api/feature-toggle' },
        dev: { featureToggles: 'https://dev-www.tombola.dk/api/feature-toggle' },
        stage: { featureToggles: 'https://stage-www.tombola.dk/api/feature-toggle' },
        live: { featureToggles: 'https://www.tombola.dk/api/feature-toggle' }
    },
    'se-se': {
        debug: { featureToggles: 'https://dev-www.tombola.se/api/feature-toggle' },
        dev: { featureToggles: 'https://dev-www.tombola.se/api/feature-toggle' },
        stage: { featureToggles: 'https://stage-www.tombola.se/api/feature-toggle' },
        live: { featureToggles: 'https://www.tombola.se/api/feature-toggle' }
    }
};

export interface IToggle {
    key: string;
    value: string;
}

class FeatureControl {

    private _toggleList: Record<string, IToggle[]> = {};

    /**
     * Loads all FeatureToggles defined in the AdminPanel for the active Environment (Dev, Stage or Live)
     */
    public load(): Promise<void> {
        const region: Locale = queryStringParams.locale ?? 'en-gb';
        const regionFeatureTogglesUrl = featureToggleUrls[region];
        if (!regionFeatureTogglesUrl) {
            console.error(`Error selecting feature toggles urls from region: ${region}`);
            return Promise.reject(`region ${region} does not exist in toggles`);
        }

        const uniqueTimestamp: number = new Date().getTime(); // anti-cache
        return axios.get(regionFeatureTogglesUrl[environment as keyof (typeof featureToggleUrls)].featureToggles + '?anti-cache=' + uniqueTimestamp)
            .then((response: { data: { featureToggles: IToggle[] } }) => {
                for (const toggle of response.data.featureToggles) {
                    const prefix = toggle.key.split('_')[0];
                    if (!this._toggleList[prefix]) {
                        this._toggleList[prefix] = [];
                    }
                    this._toggleList[prefix].push(toggle);
                }
                return;
            }).catch((error: Error) => {
                console.error('Error loading FeatureToggle API: ' + error.toString());
            }
            );
    }

    /**
     * Looks in the loaded featureToggle list for the passed key and returns it's value as a boolean.
     * Defaults to false if the key is not found and displays a console error.
     * @param key The name of the desired featureToggle matching the name on AdminPanel
     */
    public getKey(key: string): boolean {
        if (Object.keys(this._toggleList).length === 0) {
            if (environment !== 'live') {
                console.error(`Unable to find featureToggle ${key}. Defaulting to false.\n\nThe ToggleList is empty did you forget a call to FeatureToggles.load or not wait for the promise to resolve before accessing?`);
            }

            return false;
        }

        const prefix = key.split('_')[0];
        if (this._toggleList[prefix] === undefined) {
            if (environment !== 'live') {
                console.error(`Unable to find featureToggle ${key}. Defaulting to false.\n\nPrefix: (${prefix}) not found.`);
            }

            return false;
        }

        for (const toggle of this._toggleList[prefix]) {
            if (key === toggle.key) {
                return toggle.value === 'True' ? true : false;
            }
        }

        if (environment !== 'live') {
            console.error(`Unable to find featureToggle ${key}. Defaulting to false.\n\nPrefix (${prefix}) exists, but key (${key}) not found.`);
        }

        return false;
    }
}

export const featureToggles = new FeatureControl();
